const raw = String($input.first().json.output || '').trim();
const suggestionsMatch = raw.match(/^\s*SUGGESTIONS\s*:\s*(.+)$/im);
const actionMatch = raw.match(/^\s*ACTION\s*:\s*(\{.*\})\s*$/im);

let action = null;
if (actionMatch) {
  try {
    const parsed = JSON.parse(actionMatch[1]);
    const module = String(parsed?.module || '').trim().toLowerCase();
    const operation = String(parsed?.operation || '').trim().toLowerCase();
    const allowedModules = ['sauda', 'buyer', 'seller', 'commodity', 'loading', 'payment'];
    if (allowedModules.includes(module) && (operation === 'create' || operation === 'edit')) {
      action = {
        module,
        operation,
        recordKey: parsed.recordKey ? String(parsed.recordKey).trim() : '',
        fields: parsed.fields && typeof parsed.fields === 'object' ? parsed.fields : {},
      };
    }
  } catch (error) {
    action = null;
  }
}

const suggestions = suggestionsMatch
  ? suggestionsMatch[1]
      .split('|')
      .map((item) => item.trim())
      .filter(Boolean)
      .slice(0, 3)
  : [];

let content = raw;
if (suggestionsMatch) content = content.replace(suggestionsMatch[0], '');
if (actionMatch) content = content.replace(actionMatch[0], '');
content = content.trim();

return [
  {
    json: {
      content: content || "I couldn't find an answer for that. Try rephrasing or narrowing the search.",
      suggestions,
      action,
    },
  },
];
